// Etapa 3: Procesar la respuesta y extraer el top 3
const ranking = $input.first().json;

const entradas = ranking.entradas || [];

const top3 = entradas
  .filter(e => e.posicion <= 3)
  .sort((a, b) => a.posicion - b.posicion);

const medallas = ['🥇', '🥈', '🥉'];

const top3Formateado = top3.map((entrada, idx) => ({
  posicion: entrada.posicion,
  medalla: medallas[idx] || '🏅',
  nombre: entrada.nombre || `Donante #${entrada.donanteId}`,
  donanteId: entrada.donanteId,
  misionesCompletadas: entrada.misionesCompletadas
}));

const periodo = ranking.periodo || new Date().toISOString().slice(0, 7);

console.log(`Ranking ${periodo} procesado. Top 3:`, JSON.stringify(top3Formateado));

return [{
  json: {
    periodo,
    totalParticipantes: entradas.length,
    top3: top3Formateado,
    timestamp: new Date().toISOString()
  }
}];

// Etapa 4: Construir el mensaje de publicación del ranking
const data = $input.first().json;

const top3Lines = data.top3.map(
  e => `${e.medalla} ${e.nombre} — ${e.misionesCompletadas} misiones completadas`
).join('\n');

const postText = [
  `📊 Ranking DonaTrack — ${data.periodo}`,
  '',
  '¡Felicitamos a los donantes más activos del mes!',
  '',
  top3Lines,
  '',
  `Total de participantes activos: ${data.totalParticipantes}`,
  '',
  '#DonaTrack #Donaciones #RankingMensual #Solidaridad'
].join('\n');

return [{
  json: {
    ...data,
    postText
  }
}];

// Etapa 5: Notificar al backend que el ranking fue publicado y registrar resultado
const data = $('Construir Mensaje del Ranking').first().json;
const respuesta = $input.first().json;

const exitoso = respuesta.url !== undefined;

console.log(`[MOCK] Ranking ${data.periodo} publicado en red social: ${exitoso ? 'EXITOSO' : 'FALLIDO'}`);
console.log(`Top 3:`);
data.top3.forEach(e => console.log(`  ${e.medalla} ${e.nombre}: ${e.misionesCompletadas} misiones`));

return [{
  json: {
    status: 'ok',
    periodo: data.periodo,
    publicado: exitoso,
    top3: data.top3,
    mensaje: `Ranking mensual ${data.periodo} calculado y publicado correctamente (mock)`,
    timestamp: new Date().toISOString()
  }
}];
